WITH payload AS (SELECT $archive_payload$[{"id":"97e800ab-e40e-5fc8-8070-1810d375bf88","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتستر على مصدرها -األصل براءة الذمة -عدم إدانة.","document_number":"34229749","case_number":"34181757","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/04","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتستر على مصدرها -األصل براءة الذمة -عدم إدانة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34229749 :‬تاريخه‪1434/06/04 :‬هـ‬\n                     ‫رقم الدعوى‪34181757:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34251487‬تاريخه‪1434/06/26:‬هـ‬\n\n\n  ‫مخــدرات ‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتســتر علــى‬\n                       ‫مصدرهــا ‪ -‬األصــل بــراءة الذمــة ‪-‬عــدم إدانــة‪.‬‬\n\n\n\n\n                                                            ‫األصل براءة الذمة‪.‬‬\n\n\n\n  ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة حبــوب الترامــادول‬\n  ‫احملظــورة بقصــد التعاطــي‪ ،‬واحلكــم عليــه بعقوبــة الســجن واإلبعــاد‬\n  ‫عــن البــاد طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬حيــث‬\n  ‫أنــه مت تفتيــش الســيارة التــي يقودهــا فعثــر فيهــا علــى حبــوب الترامــادول‬\n  ‫احملظــورة‪ -‬أثبــت التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة املرســلة‬\n  ‫لعقــار الترامــادول‪ ،‬وأنكــر املدعــى عليــه أمــام احملكمة ما أســنده إليه‬\n  ‫املدعــي العــام مــن حيــازة حبــوب الترامــادول بقصــد التعاطــي ودفــع بأنها‬\n  ‫ضبطــت يف ســيارة مســتأجرة كان يقودهــا ولــم يعلــم بوجودهــا فيهــا‪،‬‬\n  ‫كمــا أن املدعــى عليــه ال يوجــد لــه ســوابق ونتيجــة العينــة املأخــوذة منــه‬\n  ‫ســلبية‪ ،‬مــن املقــرر شــرع ًا أن األصــل بــراءة الذمــة‪ ،‬فقضــت احملكمــة‬\n  ‫بعــدم ثبــوت دعــوى املدعــي العــام وقــررت إخــاء ســبيل املدعــى عليــه‬\n  ‫منهــا‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه وقــررت‬\n\n                                                                                       ‫‪136‬‬\n\f                                   ‫محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n      ‫اجلزائيــة باألحســاء‬\n                      ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬يف احملكمــة‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف‬\n      ‫محافظــة األحســاء املكلــف برقــم ‪ 34181757‬وتاريــخ ‪1434/04/21‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 34970628‬وتاريــخ ‪ 1434/04/21‬هـ ففي‬\n      ‫يــوم االثنــن املوافــق ‪ 1434/05/06‬ه ـ افتتحــت اجللســة األولــى الســاعة‬\n      ‫‪08 :30‬وفيهــا حضــر املدعــي العــام ‪........‬املعمــد بحضــور جلســات‬\n      ‫احملكمــة مبوجــب خطــاب رئيــس دائــرة التحقيــق واالدعــاء العــام‬\n      ‫مبحافظــة االحســاء رقــم ‪........‬وتاريــخ ‪1433/12/28‬ه ـ واحضــر معــه‬\n      ‫‪................‬مصــري اجلنســية مبوجــب اإلقامــة رقــم ‪........‬وادعــى املدعــي‬\n      ‫العــام قائــا يف دعــواه أنــه بتاريــخ ‪1434/3/14‬ه ـ وأثنــاء قيــام الدوريــات‬\n      ‫بعملهــا علــى طريــق الدمــام الريــاض مت اســتيقاف يف ســيارة مــن نــوع ‪....‬‬\n      ‫موديــل ‪2012‬م حتمــل اللوحــة رقــم (‪ )....‬بقيــادة املدعــى عليــه ‪ ،‬وعنــد‬\n      ‫طلــب اإلثبــات لوحــظ عليــه االرتبــاك ‪ ،‬وبتفتيشــه وتفتيــش املركبــة‬\n      ‫ضبــط بجانــب كابــح العجــات اليــدوي (البريــك) علــى حبــة ونصــف‬\n      ‫احلبــة حمــراء اللــون مــن احملتمــل أن تكــون مــن احلبــوب احملظــورة‪.‬‬\n      ‫وباســتجوابه أقر بصحة واقعة القبض والضبط وأن احلبوب ضبطت يف‬\n      ‫الســيارة التــي كان يســتقلها‪ .‬وقــد أثبــت التقريــر الكيمــاوي الشــرعي‬\n      ‫رقــم (‪ )........‬لعــام ‪1434‬ه ـ إيجابيــة احلبــوب املضبوطــة لعقــار الترامــادول‬\n      ‫احملظــور واملــدرج يف اجلــدول (‪ )1‬فئــة (هـ) من نظــام مكافحة املخدرات‬\n      ‫واملؤثــرات العقليــة‪ .‬وانتهــى التحقيــق إلــى توجيــه االتهــام لــه بحيــازة حبــة‬\n\n‫‪137‬‬\n\f‫ونصــف احلبــة مــن حبــوب الترامادول احملظــورة بقصد التعاطي ‪ ،‬املجرم‬\n‫مبوجــب املــادة ( الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وتســتره علــى مصــدر املخــدرات‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪ -1:‬مــا‬\n‫جــاء يف إقــراره املنــوه عنــه‪ ،‬املــدون علــى الصفحــة رقــم (‪ )2،1‬مــن دفتــر‬\n‫التحقيــق لفــه رقــم(‪ -2 .)........‬مــا جــاء يف محضــر الضبــط املرفــق لفــة‬\n‫رقــم (‪ -3 .)2‬مــا جــاء يف التقريــر الكيمــاوي للمضبوطــات املرفــق لفــة‬\n‫رقــم ( ‪ .) 20‬وحيــث إن مــا أقــدم عليــه املذكــور‪ ،‬وهــو بكامــل أهليتــه‬\n‫املعتبــرة شــرعاً‪ ،‬فعــل مجــرم ومعاقــب علي ــه نظام ـ ًا ؛ لــذا اطلــب إثبــات‬\n‫مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪ -1 :‬العقوبــة الــواردة يف الفقــرة‬\n‫األولــى مــن املــادة (‪ )41‬مــن النظـ ــام الـمشـ ــار إليـ ــه لقــاء م ــا أسن ــد إليـ ــه‪.‬‬\n‫‪ -2‬بالعقوبــة الــواردة يف الفقــرة الثانيــة مــن املادة (‪ )56‬من النظام بإبعاده‬\n‫خــارج البــاد بعــد تنفيــذ محكوميتــه‪ -3 .‬عقوبــة تعزيريــة لقــاء تســتره‬\n‫علــى مصــدر املخــدرات‪ .‬هــذه دعــواي وبعــرض الدعــوى علــى املدعــى‬\n‫عليــه أجــاب قائــا مــا ذكــره املدعــي العــام غيــر صحيــح فلــم يكــن يف‬\n‫حوزتــي حبــه ونصــف مــن حبــوب الترامــادول احملظــورة وال صلــة لــي بهــا‬\n‫ولــم أتســتر علــى احــد مــن مروجــي املخــدرات هكــذا أجــاب وبســؤال‬\n‫املدعــي العــام عــن بينتــه قــرر قائــا بينتــي مــا ذكرتــه أعــاه واطلــب‬\n‫الرجــوع إليــه هكــذا قــرر وبالرجــوع إليــه اطلعــت علــى أقــوال املدعــى‬\n‫عليــه املدونــة علــى الصفحتــن األولــى والثانيــة مــن اللفــة ‪ 11‬ومحضــر‬\n‫الضبــط املــدون علــى اللفــة الثانيــة الصــادر مــن مركــز شــرطة ‪........‬‬\n‫برقــم ‪ ........‬وتاريــخ ‪1434/3/14‬ه ـ والتقريــر الكيمــاوي الشــرعي‬\n‫الصــادر مــن املركــز االقليمــي ملراقبــة الســموم برقــم ‪........‬املرفــق علــى‬\n\n\n                                                                                                  ‫‪138‬‬\n\f      ‫اللفــة عشــرين فوجدتهــا تتضمــن مــا ذكــره املدعــي العــام كمــا تضمــن‬\n      ‫التقرير الكيماوي كون هذه احلبوب تســتخدم كمســكن يف حاالت‬\n      ‫اآلالم الشــديدة واملتوســطة وال تصــرف إال بوصفــة طبيــة وبعرضهــا علــى‬\n      ‫املدعــى عليــه قــرر قائــا أقوالــي صحيحــة فقــد كانــت احلبــة والنصــف‬\n      ‫حتــت جلــدة البريــك اليــدوي وكانــت الســيارة مســتأجرة مــن معــرض‬\n      ‫‪........‬لتأجيــر الســيارات أمــام أســواق ‪........‬شــارع ‪........‬يف مدينــة الدمــام‬\n      ‫وقــد أخــذ منــي العســاكر يف نقطــة التفتيــش عقــد إيجــار الســيارة وقــد‬\n      ‫اســتأجرت الســيارة صبــاح ذلــك اليــوم وقبــض علــي بعــد الظهــر مــن ذلــك‬\n      ‫اليــوم ولــم أكــن أعلــم عــن هــذه احلبــوب ولســت أتعاطــى أي نــوع مــن‬\n      ‫أنــواع املخــدرات وليــس لــي أي ســابقة وأمــا مــا تضمنــه محضــر تنفيــذ‬\n      ‫املهمــة مــن كونــي مرتبــك فكيــف ال ارتبــك يف موقــف مثــل هــذا وقــد‬\n      ‫اتهمــت بحيــازة املخــدرات وقــد اطلعــت علــى تقريــر الســموم الشــرعية‬\n      ‫الصــادر مــن املركــز االقليمــي ملراقبــة الســموم بالشــرقية برقــم ‪........‬‬\n      ‫املرفــق علــى للفــه ‪ 18‬فوجدتــه يتضمــن ســلبية العينــات املأخــوذة مــن‬\n      ‫املدعــى عليــه للمــواد الكحوليــة واملخــدرة واملمنوعــة وبعــرض مــا قــرره‬\n      ‫املدعــى عليــه علــى املدعــي العــام قــرر قائــا إن ارتبــاك املدعــى عليــه‬\n      ‫أثنــاء طلــب اإلثبــات منــه وال أعلــم عمــا ذكــره املدعــى عليــه عمــا إذا‬\n      ‫كانــت الســيارة مســتأجره وال يوجــد يف أوراق املعاملــة مــا يثبــت ذلــك‬\n      ‫هكــذا قــرر وبعرضــه علــى املدعــى عليــه قــرر قائــا ال بــد أن أكــون‬\n      ‫يف مثــل هــذا املوقــف فقــد حضــر إلــي ثالثــة مــن رجــال األمــن وأنزلونــي‬\n      ‫مــن الســيارة قبــل رؤيــة احلبــة وأدخلونــي داخــل املركــز وفتشــوني وال بــد‬\n      ‫أن أكــون مرتبــكا وأمــا إثباتــي علــى اســتئجار الســيارة فانــي اطلــب‬\n      ‫مهلــه لذلــك هكــذا قــرر لــذا أجبتــه لطلبــه ورفعــت اجللســة ويف جلســة‬\n\n\n‫‪139‬‬\n\f‫أخــرى يــوم الســبت املوافــق ‪1434/6/3‬ه ـ ويف متــام الســاعة الثانيــة عشــر‬\n‫والنصــف افتتحــت اجللســة الثانيــة لهــذه القضيــة وفيهــا حضــر املدعــي‬\n‫العــام واملدعــى عليــه وقــد وردنــي خطــاب املدعــى عليــه املقيــد برقــم‬\n‫‪ 34/1271424‬وتاريــخ ‪1434/5/26‬ه ـ وبرفقــه عقــد إيجــار الســيارة‬\n‫املــدون علــى مطبوعــات مؤسســة ‪........‬لتأجيــر الســيارات برقــم ‪........‬‬\n‫وتاريــخ ‪2013/1/26‬م املتضمــن اســتئجار مصــري اجلنســية ســيارة‬\n‫‪ .....‬إنتــاج ‪2012‬م رقــم لوحتهــا (‪ )....‬زرقــاء اللــون ملــدة يومــن‪ .‬و تاريــخ‬\n‫املغــادرة ‪2013/1/26‬م وهــذا التاريــخ يوافــق حســب التقــومي الهجــري‬\n‫تاريــخ القبــض علــى املدعــى عليــه ‪1434/3/14‬هــ‪ .‬فبنــاء علــى مــا ســلف‬\n‫مــن الدعــوى واإلجابــة وإنــكار املدعــى عليــه للدعــوى جملــة وتفصيــا‬\n‫وبنــاء علــى عــدم وجــود البينــة الكافيــة علــى هــذه الدعــوى وكــون‬\n‫املــكان مــكان خفيــا والســيارة مســتأجرة حســب العقــد املشــار إليــه‬\n‫أعــاه واألصــل بــراءة الذمــة الســيما مــع خلــو ســجل املدعــى عليــه‬\n‫مــن الســوابق كمــا أن تقريــر الســموم الشــرعية املشــار إليــه أعــاه‬\n‫تضمــن ســلبية العينــات املأخــوذة مــن املدعــى عليــه للمــواد الكحوليــة‬\n‫واملخــدرة واملمنوعــة وذلــك ممــا يقــوي جانــب البــراءة للمدعــى عليــه مــن‬\n‫هــذه الدعــوى وبنــاء عليــة فلــم تثبــت لــدي هــذه الدعــوى وأخليــت ســبيل‬\n‫املدعــى عليــه منهــا وبــه حكمــت وبعرضــه علــى املدعــي العــام واملدعــى‬\n‫عليــه قــرر املدعــى عليــه قناعتــه بــه وقــرر املدعــي العــام عــدم القناعــة‬\n‫وطلــب االســتئناف مكتفيــا مبــا قــدم عــن تقــدمي الئحــة اعتراضيــه‬\n‫فأجبتــه لطلبــه وقــررت بعــث املعاملــة إلــى محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية حســب التعليمــات وأقفلــت اجللســة الســاعة الواحــدة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‬\n\n\n                                                                                     ‫‪140‬‬\n\f      ‫حــرر يف ‪1434/6/3‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافــق‬\n      ‫‪1434/07/09‬ه ـ ويف متــام الســاعة الثانيــة عشــر والنصــف افتتحــت‬\n      ‫اجللســة الثالثــة املتعلقــة بدعــوى املدعــي العــام ضــد ‪ ....‬وقــد عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف مــن باملنطقــة الشــرقية باخلطــاب‬\n      ‫ذي الرقــم ‪ 341495615‬والتاريــخ ‪1434/07/03‬ه ـ ومرفــق بهــا قــرار‬\n      ‫محكمة االســتئناف ذي الرقم ‪ 34251487‬والتاريخ ‪1434/06/26‬هـ‬\n      ‫املتضمــن مــا نصــه (وبدراســة القــرار وصــورة ضبطــه أوراق املعاملــة‬\n      ‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق) وحتــى ال يخفــى جــرى‬\n      ‫إثباتــه وأقفلــت اجللســة الســاعة الواحــدة وبــاهلل التوفيــق وصلــى اهلل‬\n          ‫علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم حــرر ‪1434/07/09‬ه ـ‬\n\n\n\n\n‫‪141‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":136,"source_page_end":141,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6c82711ff5c15e639eb2ddd7da3ba1a92f152f091bb8e63e9ecc6308baebee01","normalized_text_hash":"16232fc1b230c7f3c8a77c4340d795282c31652d444bade5a3ca186319cc89e5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p136-34229749"},{"id":"d01101f8-5673-5b61-b581-14fa228b5222","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -اإلمفيتامن -حيازة حبوب محظورة بقصد التعاطي -تعاطي حبوب محظورة -إقرار حتقيق ا -ثبوت إدانة -نزول عن احلد األدنى للعقوبة -تعزير بالسجن واملنع من السفر.","document_number":"34263039","case_number":"34183298","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة املخواة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/09","year":"1434","subject":"مخدرات -اإلمفيتامن -حيازة حبوب محظورة بقصد التعاطي -تعاطي حبوب محظورة -إقرار حتقيق ا -ثبوت إدانة -نزول عن احلد األدنى للعقوبة -تعزير بالسجن واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34263039 :‬تاريخه ‪1434/07/09 :‬هـ‬\n                     ‫رقم القضية ‪34183298 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 34321411‬تاريخه‪1434/9/17:‬هـ‬\n\n\n  ‫مخــدرات ‪ -‬اإلمفيتامــن ‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي‬\n  ‫‪ -‬تعاطــي حبــوب محظــورة ‪ -‬إقــرار حتقيقـ ًا ‪ -‬ثبــوت إدانــة ‪ -‬نــزول عــن‬\n            ‫احلــد األدنــى للعقوبــة ‪ -‬تعزيــر بالســجن واملنــع مــن الســفر‪.‬‬\n\n\n\n\n   ‫املواد ( ‪ ) 60 - 56 - 41‬من نظام مكافحة املخدرات و املؤثرات العقلية‬\n\n\n\n\n  ‫الئحــة الدعــوى ضــد املدعــى عليــه بحيــازة حبــة حتتوي علــى اإلمفيتامني‬\n  ‫احملظــور بقصــد التعاطــي‪ ،‬طلــب املدعــي العــام إثبــات مــا أســند إليــه‬\n  ‫واحلكــم عليــه بالســجن واملنــع مــن الســفر‪ ،‬مت القبــض علــى املدعــى‬\n  ‫عليــه بعــد االشــتباه بــه حيــث كان متوقفـ ًا يف مــكان مظلــم وباالقتراب‬\n  ‫منــه مــن قبــل الدوريــات لوحــظ عليــه االرتبــاك وبتفتيشــه عثــر معــه علــى‬\n  ‫حبــة واحــدة محظــورة وباســتجوابه أقــر بحيازتهــا بقصــد التعاطــي‪،‬‬\n  ‫إقــرار املدعــى عليــه بالدعــوى‪ ،‬تعزيــر املدعــى عليــه بالســجن واملنــع مــن‬\n                                                                          ‫الســفر‪.‬‬\n\n\n\n\n                                                                                      ‫‪142‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنا ‪ ........‬رئيــس احملكمة العامة مبحافظة‬\n      ‫املخــواة وبنــاء علــى املعاملــة الــواردة إلينــا مــن هيئــة التحقيــق واالدعــاء‬\n      ‫العــام مبحافظــة املخــواة برقــم هــ‪/8‬م‪ 622/2‬يف ‪1434/4/20‬ه ـ ففــي‬\n      ‫يــوم األحــد املوافــق‪ 1434/07/09‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 00‬‬\n      ‫وفيهــا حضــر املدعــي العــام مبحافظــة املخــواة ‪ ........‬ســعودي بالســجل‬\n      ‫املدني رقم ‪ .....‬وحضر حلضوره ‪ ........‬سعودي اجلنسية مبوجب السجل‬\n      ‫املدنــي رقــم ‪ ........‬وقــال املدعــي العــام يف حتريــر دعــواه حيــث إنــه بتاريــخ‬\n      ‫‪1433/12/29‬ه ـ وأثنــاء قيــام إحــدى فــرق مكافحــة املخــدرات مبنطقة‬\n      ‫‪ .....‬بالبحــث عــن مروجــي وحائــزي املــواد احملظــورة مبحافظــة ‪ .....‬ويف‬\n      ‫حوالــي الســاعة احلاديــة عشــرة مســاء ًا اشــتبهت الفرقــة باملذكــور‬\n      ‫أعــاه حيــث كان يســتقل ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم (‪)....‬‬\n      ‫ومتوقــف يف موقــع مظلــم مثيــر للشــبهة ‪ ،‬وباقتــراب الفرقــة منــه لوحــظ‬\n      ‫عليــه االرتبــاك وبتفتيشــه عثــر يف جيــب ثوبــه الســفلي علــى حبــة واحــدة‬\n      ‫يشــتبه أنهــا محظــورة فتــم القبــض عليــه وأثبــت التقريــر الكيميائــي‬\n      ‫الشــرعي رقــم ( ‪ )...../.. /....‬احتــواء احلبــة املضبوطــة علــى مــادة‬\n      ‫اإلمفيتامــن احملظــورة وباســتجوابه أقــر بحيــازة حبــة واحــدة محظــورة‬\n      ‫بقصــد التعاطــي وأنــه لــم يســبق لــه تعاطــي املــواد احملظــورة وقــد حصــل‬\n      ‫عليهــا مــن شــخص يدعــى ‪ ............‬وقــد أدلــى املذكــور مبعلومــات عنــه‬\n      ‫للفرقــة القابضــة وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام لــه بحيازة‬\n      ‫حبــة واحــدة حتتــوي علــى مــادة اإلمفيتامــن احملظــورة بقصــد التعاطي ‪،‬‬\n      ‫احملــرم شــرع ًا واملجــرم نظامـ ًا مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة‬\n\n‫‪143‬‬\n\f‫مــن نظــام مكافحــة املخــدرات الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n                    ‫وتاريــخ ‪1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪ -1‬أقوالــه املدونــة علــى الصفحــة (‪ )18‬مــن ملــف ضبــط إجــراءات‬\n‫االست ــدالل يف قضـ ــايا املخـ ــدرات الـمـ ــرفق لف ـ ــة (‪ )1‬ولف ـ ــة (‪.)15/14‬‬\n‫‪ -2‬محضــر القبــض والتفتيــش املنــوه عنــه املــدون صفحــة (‪ )11‬مــن‬\n‫ملــف ضبـ ــط إجــراءات االستـ ــدالل يف قضـ ــايا املخ ـ ــدرات املرفــق لفــة‬\n‫(‪ -3 .)1‬التقريــر الكيميائــي الشــرعي املرفــق لفــة (‪ )24‬وحيــث إن مــا‬\n‫أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم‬\n‫شــرع ًا ومجــرم نظام ـ ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم‬\n‫عليــه مبــا يلــي ‪ -1:‬ســجنه لقــاء مــا أســند إليــه اســتنادا للفقــرة األولــى‬\n‫مــن املــادة احلاديــة واألربعــن مــن نظــام مكافحــة املخــدرات املشــار إليــه‬\n‫‪ -2‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد تنفيــذ عقوبتــه اســتناد ًا‬\n‫للفقــرة األولــى مــن املــادة السادســة واخلمســن مــن ذات النظــام وبــاهلل‬\n‫التوفيــق وبعــرض مــا جــاء يف الئحــة الدعــوى علــى املدعــى عليــه أجــاب‬\n‫مــا ورد يف الئحــة الدعــوى مــن توجيــه االتهــام لــي بحيــازة حبــة واحــدة‬\n‫حتتــوي علــى مــادة اإلمفيتامــن بقصــد التعاطــي فهــو صحيــح وأنــا تائــب‬\n‫ونــادم أشــد النــدم أطلــب النظــر يف وضعــي هــذه إجابتــي فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة ونظــرا إلقــرار املدعــى عليــه مبــا نســب إليــه‬\n‫يف هــذه الدعــوى وبنــاء علــى التقريــر الكيميائــي الشــرعي املنــوه عنــه‬\n‫وخللــو صحيفــة املدعــى عليــه مــن الســوابق املســجلة عليــه ولقلــة الكميــة‬\n‫احملــازة وبنــاء علــى املــادة ‪ 41‬و‪ 56‬و‪ 60‬مــن نظــام املخــدرات وجلميــع‬\n‫مــا تقــدم فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة حبــه مــن حبــوب‬\n‫اإلمفيتامــن احملظــورة وحكمــت مبــا يلــي ‪1‬ـ ســجن املدعــى عليــه ملــدة‬\n\n\n                                                                                      ‫‪144‬‬\n\f      ‫خمســة عشــر يومــا ‪2‬ـ منعــه مــن الســفر ملــدة ســنتني خلــارج اململكــة بعــد‬\n      ‫انتهــاء مــدة محكوميتــه وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n      ‫عليــه القناعــة وقــرر املدعــي العــام عدمهــا وطلــب االســتئناف بالئحــة‬\n      ‫فجــرى إفهامــه بتعليمــات االســتئناف وصلــى اهلل علــى نبينــا محمــد‬\n                        ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/09‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد يف يــوم اخلميــس ‪1434/8/25‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة الثامنــة والربــع وقــد انتهــت املــدة النظاميــة لالعتــراض ولــم‬\n      ‫تردنــا الالئحــة االعتراضيــة مــن املدعــي العــام ونظــر ًا ملــا تضمنتــه املــادة‬\n      ‫‪ 195‬مــن نظــام اإلجــراءات اجلزائيــة ســيجري رفــع كامــل املعاملــة‬\n      ‫حملكمــة االســتئناف لتدقيــق مــا جــاء يف احلكــم وبــاهلل التوفيــق وصلــى‬\n                                                           ‫اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملخــواة الشــيخ‪ ............‬برقــم ‪ ........‬وتاريــخ‬\n      ‫‪1434/9/2‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلتــه برقــم وتاريــخ‬\n      ‫‪1434/7/9‬ه ـ املتضمــن دعــوى املدعــي العــام ضــد‪ ............‬املدعــى‬\n      ‫عليــه‪ ،‬املتهــم بحيــازة حبــة واحــدة محظــورة بقصــد التعاطــي احملكــوم‬\n      ‫فيــه مبــا دون باطــن القــرار‪ .‬وبدراســة القــرار وصــورة ضبطــه تقــررت‬\n      ‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                      ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪145‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":142,"source_page_end":145,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7821d34f1899911641438c56d463acd7d8554b18e8bcd0ae560a26776af481c9","normalized_text_hash":"3372ad3bb95ac4aa90125811b834cbf1f3bd82f94b368838f47ccab0cc16d443","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p142-34263039"},{"id":"78582c4d-587e-538e-80f0-a9e5cefb42be","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب احملظورة لقصد االستعمال -استعمال احلبوب احملظورة -ترك عقاب املدعى عليه للجهة املختصة لقاء حيازة احلبوب احملظورة قبل سريان نظام مكافحة املخدرات - التعزير باجللد.","document_number":"34212703","case_number":"34148439","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملويه","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/13","year":"1434","subject":"مخدرات -حيازة احلبوب احملظورة لقصد االستعمال -استعمال احلبوب احملظورة -ترك عقاب املدعى عليه للجهة املختصة لقاء حيازة احلبوب احملظورة قبل سريان نظام مكافحة املخدرات - التعزير باجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34212703 :‬تاريخه ‪1434/5/13:‬هـ‬\n                    ‫رقم القضية ‪34148439:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34311420‬تاريخه‪1434/09/02 :‬هـ‬\n\n\n ‫مخــدرات‪ -‬حيــازة احلبــوب احملظــورة لقصــد االســتعمال ‪ -‬اســتعمال‬\n ‫احلبــوب احملظــورة ‪ -‬تــرك عقــاب املدعــى عليــه للجهــة املختصــة لقــاء‬\n ‫حيــازة احلبــوب احملظــورة قبــل ســريان نظــام مكافحــة املخــدرات ‪-‬‬\n                                                          ‫التعزيــر باجللــد‪.‬‬\n\n\n\n            ‫إن الشريعة جاءت بحفظ الضروريات اخلمس ومنها العقل‪.‬‬\n\n\n\n\n ‫الئحــة الدعــوى ضــد املدعــى عليــه مواطــن بحيــازة احلبــوب احملظــورة‬\n ‫بقصــد االســتعمال وتعاطيــه لهــا يف الســابق‪ ،‬وطلــب املدعــي العــام‬\n ‫إثبــات مــا اســند إليــه واحلكــم عليــه وفق ـ ًا للمــادة (‪ )41‬مــن نظــام‬\n ‫مكافحــة املخــدرات واملؤثــرات العقليــة ومنعــه مــن الســفر وفقـ ًا لــذات‬\n ‫النظــام‪ ،‬مت القبــض علــى املدعــى عليــه حليازتــه عــدد مــن احلبــوب‬\n ‫احملظــورة‪ ،‬إقــرار املدعــى عليــه بالدعــوى‪ ،‬تــرك مجــازاة املدعــى عليــه‬\n ‫لقــاء حيازتــه للحبــوب احملظــورة لولــي األمــر كــون القضيــة وقعــت قبــل‬\n ‫ســريان نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬تعزيــر املدعــى‬\n ‫عليــه باجللــد لقــاء اســتعمال احلبــوب احملظــورة‪ ،‬تصديــق احلكــم مــن‬\n ‫محكمــة االســتئناف مبكــة املكرمــة بالقــرار رقــم ‪ 34311420‬يف‬\n                                                               ‫‪1434/9/2‬هــ‪.‬‬\n                                                                                  ‫‪146‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬رئيــس احملكمــة العامــة باملويــه‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن قســم اإلحــاالت برقــم ‪34148439‬‬\n      ‫وتاريــخ ‪ 1434/04/01‬ه ـ املقيــدة باحملكمــة برقــم ‪34790440‬وتاريــخ‬\n      ‫‪ 1434/04/01‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/05/11‬ه ـ افتتحت‬\n      ‫اجللســة الســاعة التاســعة ولــم تضبــط القضيــة يف النظــام الشــامل يف‬\n      ‫نفــس يــوم اجللســة لوجــود خلــل يف شــبكة االتصــاالت وفيهــا حضــر‬\n      ‫املدعــي العــام إلدارة مكافحــة املخــدرات بالطائــف الرقيــب اول ‪.........‬‬\n      ‫واملدعــى عليــه ‪ .........‬ســعودي اجلنســية بالهويــة رقــم (‪ ).........‬وقــدم‬\n      ‫املدعــي العــام الئحــة ادعــاء عــام هــذا نصهــا ادعــي أنــا الرقيــب أول‪/‬‬\n      ‫‪ .........‬املدعــي العــام ملكافحــة املخــدرات مبحافظــة الطائــف علــى‬\n      ‫املدعــو‪ .........‬ســعودي اجلنســية بالهويــة رقــم (‪ ).........‬املقبــوض عليــه يف‬\n      ‫قضيــة مخــدرات بتاريــخ ‪1425/6/19‬ه ـ مــن قبــل مكافحــة املخــدرات‬\n      ‫مبحافظــة الطائــف حليازتــه عــدد (ســبع حبــات) مــن احلبــوب احملظــورة‬\n      ‫لقصــد االســتعمال واالســتعمال لهــا مــن الســابق وذلــك لألدلــة التاليــة‪:‬‬\n      ‫‪1‬ـ مــا جــاء يف محضــر القبــض والتفتيــش املــدون علــى صفحــة (‪ )1‬مــن‬\n      ‫ملــف التحقيــق املرفــق لفــة(‪2 )1‬ـ ـ مــا جــاء يف اعترافــه املصــدق شــرع ًا‬\n      ‫واملــدون علــى الصفحــة رقــم(‪ )5‬مــن ملــف التحقيــق ‪ 3‬ـ ما جــاء يف التقرير‬\n      ‫الكيميائــي الشــرعي املرفــق رقــم (‪ ).........‬املتضمــن ايجابيــة مــا ضبــط‬\n      ‫ملــادة اإلمفيتامــن احملظــورة ‪4‬ـ ـ مــا جــاء يف صحيفــة الســوابق ووجــود‬\n      ‫ســابقة مخدرات دليل على ســوء ســلوكه وعدم اســتقامته واملدونة على‬\n      ‫لفــة (‪ )15‬عليــه أطلــب مــن فضيلتكــم إثبــات إدانــة املذكــور مبــا نســب‬\n\n‫‪147‬‬\n\f‫إليــه ومجازاتــه بعقوبــة تعزيزيــه وفقـ ًا للمــادة [‪ ]41‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39‬‬\n‫يف ‪1426/7/8‬ه ـ ومنعــه مــن الســفر وفــق املــادة [‪ ]56‬مــن نفــس النظــام‬\n‫انتهــى وبعــرض الدعــوى علــى املدعــى عليــه صــادق علــى كل مــا جــاء‬\n‫فيهــا جملــة وتفصيــا وقــال نعــم لقــد قبــض علــي وبحوزتــي ســبع حبــات‬\n‫مــن احلبــوب احملظــورة لقصــد االســتعمال وقــد اســتعملتها مــن الســابق‬\n‫وانــي تائــب الــى اهلل مــن عملــي هــذا وقــد جــرى اطالعــي علــى التقريــر‬\n‫الكيميائــي الشــرعي املرفــق يف اللفــة رقــم ‪ 13‬ويحمــل الرقــم ‪ .........‬يف‬\n‫‪1425/6/24‬ه ـ املتضمــن بفــض احلــرز واجــراء الكشــف الكيميائــي‬\n‫الشــرعي ثبــت االتــي حــرز عبــارة عــن لفافــه مــن القمــاش محــرزه بســلك‬\n‫معدنــي مختــوم بدمغــه رصاصيــة معلــق بهــا كــرت دون عليــه الرقــم‬\n‫(‪ )25/516‬بداخلهــا ســتة اقــراص برتقاليــة اللــون حتمــل العالمــة‬\n‫املعتــادة لعقــار الكبتاجــون ثبــت انهــا حتتــوي علــى مــادة االمفيتامــن‬\n‫‪.‬االمفيتامــن مــن املــواد املنبهــة للجهــاز العصبــي املركــزي وهــو مــن‬\n‫املــواد املدرجــة بجــدول املــواد املخــدرة الصــادرة بتعميــم وزارة الصحــة‬\n‫رقــم ( ‪ )27/1433/243‬يف ‪1492/5/13‬ه ـ وتعميــم وزارة الداخليــة‬\n‫رقــم (‪)42264/19‬يف ‪1494/11/18‬ه ـ اســتهلكت العينــة يف الفحــص‬\n‫انتهــى التقريــر كمــا اطلعــت علــى صحيفة ســوابق املدعــى عليه يف اللفة‬\n‫رقــم ‪14‬واملتضمنــة وجــود ثــاث ســوابق اثنتــان منهــا اســتعمال للحبــوب‬\n‫املخــدرة والثالثــة الهــروب عــن الدوريــة ومضاربــة رجــل امــن فبنــاء علــى‬\n‫مــا ســبق مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه بحيازتــه للحبــوب‬\n‫احملظــورة بقصــد االســتعمال واســتعمالها مــن الســابق ومــا جــرى‬\n‫اطالعــي عليــه مــن التقاريــر الكيميائيــة وصحيفــة ســوابق املدعــى‬\n\n\n                                                                                   ‫‪148‬‬\n\f      ‫عليــه ومبــا ان الشــريعة جــاءت بحفــظ الضروريــات اخلمــس ومنهــا العقــل‬\n      ‫ولقلــة الكميــة املضبوطــة مــع املدعــى عليــه وإظهــاره التوبــة والنــدم علــى‬\n      ‫مــا حصــل منــه لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيازتــه‬\n      ‫لعــدد ســبع حبــات مــن حبــوب االمفيتامــن احملظــورة بقصــد االســتعمال‬\n      ‫واســتعماله لهــا مــن الســابق وقــررت مــا يلــي ‪ :‬أو ًال ‪ :‬صــرف النظــر عــن‬\n      ‫طلــب املدعــي العــام تعزيــر املدعــى عليــه حيــال احليــازة واالســتعمال‬\n      ‫وتطبيــق املادتــن احلاديــة واالربعــن والسادســة واخلمســن مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك لكــون القضيــة وقعــت‬\n      ‫قبــل ســريان العمــل بنظــام مكافحــة املخــدرات املذكــور ثانيــا تعزيــر‬\n      ‫املدعــى عليــه بجلــده خمســة واربعــن جلــدة تكــرر عليــه مرتــن بينهمــا‬\n      ‫مــدة ال تقــل عــن عشــرة ايــام ثالثــا افهمــت املدعــى عليــه بــان عقابــه علــى‬\n      ‫حيازتــه للحبــوب احملظــورة عائــد لولــي االمــر هــذا مــا ظهــر لــي وبــه‬\n      ‫حكمــت وبعرضــه علــى املدعــي العــام قــرر االعتــراض بــدون الئحــة‬\n      ‫اعتراضيــة كمــا قــرر املدعــى عليــه قناعتــه باحلكــم وعليــه اغلقــت‬\n      ‫اجللســة الســاعة التاســعة والنصــف ‪ 0‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/11‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء ‪ 1434/10/6‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة الثامنــة وقــد عــادت املعاملــة مــن فضيلــة رئيــس‬\n      ‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة برقــم ‪341997736‬‬\n      ‫بتاريــخ ‪1434/9/13‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائرة‬\n      ‫اجلزائيــة الســابعة رقــم ‪ 34311420‬بتاريــخ ‪1434 /9 /2‬ه ـ ونــص احلاجــة‬\n      ‫منــه ( بدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم )‬\n      ‫انتهــى وعليــه أغلقــت اجللســة الســاعة الثامنــة والنصــف عشــر وصلــى‬\n\n\n‫‪149‬‬\n\f‫اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم حــرر ‪1434/10/6‬ه ـ‬\n\n\n\n\n                                                                           ‫‪150‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":146,"source_page_end":150,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"77f8e8e6673b65c22929ea4bdfcbcfe6343250730bb15f818325ddcb0f5f06ea","normalized_text_hash":"185b3c43df286b1341fd11dcd9ccdac3a0b999921bccf35779354be2a0d682ec","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p146-34212703"},{"id":"f7baf681-e5bc-51cd-bdc3-7a94c1c633cc","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر - مقاومة رجال األمن -املدعى عليه أصم وأبكم -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير باحلبس واملنع من السفر .","document_number":"34217687","case_number":"34215120","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/20","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر - مقاومة رجال األمن -املدعى عليه أصم وأبكم -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير باحلبس واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34217687 :‬تاريخه‪1434/05/20 :‬هـ‬\n                          ‫رقم الدعوى‪34215120:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪34234383‬تاريخه‪1434/6/7:‬هـ‬\n\n\n       ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه‪ -‬حــد املســكر ‪-‬‬\n       ‫مقاومــة رجــال األمــن ‪ -‬املدعــى عليــه أصــم وأبكــم‪ -‬إقــرار‪ -‬إدانــة‪ -‬نــزول‬\n         ‫عــن احلــد األدنــى للعقوبــة ‪ -‬التعزيــر باحلبــس واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n       ‫املــواد (‪ )41‬و (‪ )56‬و (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                  ‫العقليــة‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش املخــدر‬\n       ‫بقصــد التعاطــي وتعاطيــه لــه‪ ،‬ومقاومتــه رجــال األمــن ومحاولــة الهــرب‬\n       ‫منهــم‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبق ـ ًا لنظــام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة وعقوبــة تعزيريــة علــى باقــي‬\n       ‫التهــم‪ ،‬حيــث إنــه مت اســتيقافه بعــد ظهــور عالمــات االرتبــاك عليــه‬\n       ‫فقــام برمــي علبــة دخــان بداخلهــا قطعــة وفــرط تبــغ مــن احلشــيش‬\n       ‫املخدر‪،‬وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n       ‫للحشــيش املخــدر‪ ،‬وأقــر املدعــى عليــه أمــام احملكمــة بواســطة‬\n       ‫مترجمــن اثنــن للغــة اإلشــارة حيــث انــه أصــم وأبكــم مبــا أســنده‬\n       ‫إليــه املدعــي العــام‪ ،‬وحيــث أنــه أبــدى التوبــة وال يوجــد لــه ســوابق‬\n\n‫‪151‬‬\n\f‫مــن نفــس جنــس اجلرميــة والكميــة احملــازة قليلــة‪ ،‬فقضــت احملكمــة‬\n‫بإدانــة املدعــى عليــه بحيــازة احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه‬\n‫لــه وقــررت ســجنه ملــدة شــهرين ومنعــه مــن الســفر خــارج اململكــة ملــدة‬\n‫ســنتني وبجلــد ثمانــن جلــدة دفعــة واحــدة ( حــد املســكر ) يف مــكان‬\n‫عــام وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬قــررت‬\n                          ‫محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة القطيــف بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة القطيــف برقــم ‪ 34215120‬وتاريــخ‬\n‫‪1434/05/08‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341146125‬وتاريــخ‬\n‫‪1434/05/08‬ه ـ ففــي يــوم االثنــن ‪ 1434/05/20‬ه ـ افتتحــت اجللســة‬\n‫األولــى الســاعة ‪ 11 :30‬وفيهــا حضــر املدعــي العــام بصفتــي مدعي ـ ًا‬\n‫عامــا يف دائــرة التحقيــق واالدعــاء العــام مبحافظــة القطيــف أدعــي‬\n‫علــى البالــغ مــن العمــر (‪ )37‬عام ـ ًا ‪ ........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم (‪ )........‬غيــر محصــن عاطــل عــن العمــل أوقــف‬\n‫بتاريــخ ‪1434/3/18‬ه ـ وأحيــل لســجن محافظــة القطيــف وفقـ ًا لبرقيــة‬\n‫صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر‬\n‫الداخليــة رقــم (‪ )79425/4/5/1‬وتاريــخ ‪1432/12/20‬ه ـ حيــث أنــه‬\n‫بتاريــخ ‪1434/3/17‬ه ـ توفــرت معلومــات لرجــال مكافحــة املخــدرات‬\n‫عــن وجــود أشــخاص بشــارع ‪........‬بالقطيــف يتعاطــون املــواد املخــدرة‬\n‫وباالنتقــال للموقــع شــوهد املدعــى عليــه مترجــا علــى قدميــه وعنــد‬\n\n                                                                                  ‫‪152‬‬\n\f      ‫االقتــراب منــه ظهــرت عليــه عالمــات االرتبــاك وبطلــب إثباتــه قــام برمــي‬\n      ‫علبــة دخــان اتضــح أن مــا قــام برميــه بداخلــه قطعــة تــزن ثالثــة مــن‬\n      ‫العشــرة مــن اجلــرام وأيضـ ًا عثــر علــى فــرط تبــغ يــزن خمســة مــن العشــرة‬\n      ‫مــن اجلــرام وقــاوم رجــال الضبــط وحــاول الهــرب فتــم القبــض عليــه أثبــت‬\n      ‫التقريــر الكيمــاوي الشــرعي رقــم (‪ )........‬وتاريــخ ‪1434/3/24‬ه ـ‬\n      ‫ايجابيــة القطعــة املضبوطــة ملــادة احلشــيش املخــدر واحتــواء مــا ضبــط‬\n      ‫مــن تبــغ علــى مــادة احلشــيش املخــدر وباســتجوابه اقــر بصحــة واقعــة‬\n      ‫الضبــط وان مــا ضبــط بحوزتــه عائــد لــه بقصــد التعاطــي وانــه يتعاطــى‬\n      ‫احلشــيش املخــدر وأســفر التحقيــق معــه إلــى توجيــه االتهــام لــه بحيازتــه‬\n      ‫قطعــة مــن مــادة احلشــيش املخــدر تــزن ثالثــة مــن العشــرة مــن اجلــرام‬\n      ‫وتبــغ يــزن خمســة مــن العشــرة مــن اجلــرام ممــزوج باحلشــيش املخــدر‬\n      ‫بقصــد التعاطــي وتعاطيــه لــه ومقاومتــه رجــال األمــن ومحاولتــه الهــرب‬\n      ‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1‬اعترافــه مبــا اســند إليــه املرفــق علــى‬\n      ‫اللفتــن رقــم (‪ -2 )10-9‬محضــر واقعــة القبــض والتفتيــش املــدون علــى‬\n      ‫الصفحــة رقــم(‪ )11‬مــن ملــف ضبــط إجــراءات قضيــة مخــدرات لفــة رقــم‬\n      ‫(‪ -3 )1‬التقريــر الكيمــاوي املرفــق علــى اللفــة رقــم (‪ -4 )11‬محضــر‬\n      ‫التحريــز املرفــق علــى اللفــة رقــم (‪ )2‬وبالبحــث عــن ســوابقه لــم يعثــر‬\n      ‫لــه علــى ســوابق جنائيــة مســجلة وحيــث إن مــا أقــدم عليــه املذكــور‬\n      ‫وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫ونظامـ ًا لــذا أطلــب إثبــات مــا أســند إليــه وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة‬\n      ‫رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم‬\n      ‫عليــه مبــا يلــي ‪ -1‬بعقوبــة الســجن الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n      ‫رقــم (‪ )41‬مــن النظــام ‪ -2‬منعــه مــن الســفر وفق ـ ًا للفقــرة رقــم (‪ )1‬مــن‬\n\n\n‫‪153‬‬\n\f‫املــادة رقــم (‪ )56‬مــن النظــام ‪ -3‬احلكــم عليــه بعقوبــة تعزيريــة تزجــره‬\n‫وتــردع غيــره لقــاء محاولتــه الهــرب مــن رجــال األمــن و التشــديد عليــه‬\n‫وفقــا لتعميــم وزيــر الداخليــة رقــم(‪ )118012‬وتاريــخ ‪1430/10/26‬ه ـ‬\n‫ملقاومتــه رجــال األمــن هــذه دعــواي والســام وعنــد عــرض الدعــوى علــى‬\n‫املدعــى عليــه تبــن أنــه أصــم أبكــم ال يتكلــم وال يســمع وقــد حضــر‬\n‫مترجمــا اإلشــارة ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪ ........‬و‪........‬‬\n‫ســعودي بالســجل املدنــي رقــم ‪ ........‬وبعــرض دعــوى املدعــي العــام‬\n‫علــى املدعــى عليــه عبــر اإلشــارة املفهمــة قــال مــا ذكــره املدعــي العــام‬\n‫ضــدي مــن القبــض علــي يف تاريــخ ‪1434/3/17‬ه ـ والعثــور بحوزتــي‬\n‫علــى قطعــة حشــيش مخــدر صغيــرة وزنهــا ثالثــة أعشــار اجلــرام لقصــد‬\n‫التعاطــي وتعاطــي احلشــيش املخــدر وأيض ـ ًا عنــد القبــض علــي حصــل‬\n‫مقاومــة يســيرة خلــويف وعــدم معرفتــي رجــال مكافحــة املخــدرات كل‬\n‫ا وهــي املــرة األولــى واألخيــرة وأتعهــد بعــدم‬  ‫ذلــك صحيــح جملـ ًة وتفصيـ ً‬\n‫تكــراره هــذا وقــد جــرى االطــاع علــى أقــوال املدعــى عليــه أثنــاء‬\n‫التحقيــق معــه املدونــة علــى لفــة رقــم (‪ )11-10‬فوجدتهــا موافقــة لدعــوى‬\n‫املدعــي العــام كمــا جــرى االطــاع علــى محضــر قبــض املرفــق املــدون‬\n‫علــى صفحــة (‪ )11‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ )1‬فوجدتــه‬\n‫موافق ـ ًا لدعــوى املدعــي العــام كمــا جــرى االطــاع علــى التقريــر‬\n‫الكيمــاوي الشــرعي املرفــق لفــة رقــم (‪ )11‬فوجدتــه كمــا ذكــر‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلــى مصادقــة املدعــى عليــه‬    ‫فبنـ ً‬\n‫علــى دعــوى املدعــي العــام وإلــى شــهادة املترجمــن علــى إشــارة املدعــى‬\n‫عليــه ومــا تــدل عليــه أوراق املعاملــة وإلــى مــا تــدل عليــه املادتــان الواحــدة‬\n‫واألربعــون والسادســة واخلمســون مــن نظــام مكافحــة املخــدرات وإلــى‬\n\n\n                                                                                           ‫‪154‬‬\n\f      ‫عــدم ســوابق املدعــى عليــه وقلــة الكميــة وندمــه وإلى حالــة املدعى عليه‬\n      ‫ومــا تــدل عليــه املــادة الســتون مــن نظــام مكافحــة املخــدرات لــكل مــا‬\n      ‫ســبق فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة قطعــة حشــيش مخــدر‬\n      ‫وزنهــا ثالثــة أعشــار اجلــرام لقصــد التعاطــي وتعاطيــه احلشــيش املخــدر‬\n      ‫وبعــده حكمــت مبــا يلــي أو ًال بســجن املدعــى عليــه ملــدة شــهرين اعتبــار ًا‬\n      ‫مــن تاريــخ إيداعــه الســجن تطبيقـ ًا للمــادة الواحــدة واألربعــن مــن نظــام‬\n      ‫مكافحــة املخــدرات وقــد مت النــزول عــن احلــد األدنــى إعمــا ًال للمــادة‬\n      ‫الســتني مــن ذات النظــام ثاني ـ ًا منعــه مــن الســفر للخــارج ملــدة ســنتني‬\n      ‫اعتبــار ًا مــن تاريــخ انتهــاء فتــرة ســجنه ثالث ـ ًا بجلــده ثمانــن جلــدة دفعــة‬\n      ‫واحــدة حــد املســكر يف مــكان عــام وبعــرض احلكــم علــى الطرفــن‬\n      ‫قــرر املدعــى عليــه القناعــة واملدعــي العــام عدمهــا وطلــب االســتئناف‬\n      ‫وأجيــب لطلبــه كمــا قــرر ان الئحتــه االعتراضيــة مــا يف أوراق املعاملــة‬\n      ‫وأمــرت برفــع كامــل أوراق املعاملــة إلــى محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية أغلقــت اجللســة يف متــام الســاعة ‪ 12 :00‬وصلــى اهلل علــى نبينــا‬\n                                                  ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي القاضــي يف احملكمــة اجلزائيــة مبحافظــة‬\n      ‫القطيــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة مبحافظــة القطيف برقــم ‪ 34215120‬وتاريخ ‪1434/05/08‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 341146125‬وتاريــخ ‪ 1434/05/08‬ه ـ ففــي‬\n      ‫يــوم األحــد املوافــق ‪ 1434/06/18‬ه ـ افتتحــت اجللســة الســاعة ‪08 :45‬‬\n      ‫وقــد عــادت املعاملــة مــن محكمة االســتئناف باملنطقة الشــرقية مبوجب‬\n      ‫خطابهــم رقــم ‪ 341283910‬وتاريــخ ‪1434/06/12‬ه ـ واملقيــدة لدينــا‬\n      ‫برقــم ‪ 341283910‬وتاريــخ ‪1434/06/17‬ه ـ وبرفقهــا القــرار الصــادر‬\n\n\n‫‪155‬‬\n\f‫مــن قضــاة محكمــة االســتئناف الدائــرة اجلزائيــة الثالثيــة الثانيــة ‪-‬‬\n‫ج‪ 2/‬رقــم ‪ 34234383‬يف ‪1434/06/07‬ه ـ واملتضمــن املصادقــة علــى‬\n‫احلكــم وبــه تعتبــر القضيــة منتهي ــة وأغلق ــت اجلـلسـ ــة يف تـم ــام الســاعة‬\n       ‫‪ 08 :59‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪156‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":151,"source_page_end":156,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f1ee145009a8d2c7853841be6f94f795dbf428f1e1b490d75f8acab6a862cc1f","normalized_text_hash":"bf0b42ac4b88953119408f12badc86c6c40a9eb0ee45b34e4e268d0f05727f9c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p151-34217687"},{"id":"791efb80-b865-5b1c-af23-775b30553b21","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد الترويج -قات -هروب -التعزير بالسجن واجللد والغرامة مالية.","document_number":"34262414","case_number":"34222506","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/9","year":"1434","subject":"مخدرات -حيازة بقصد الترويج -قات -هروب -التعزير بالسجن واجللد والغرامة مالية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34262414 :‬تاريخه‪1434/7/9 :‬هـ‬\n                        ‫رقم القضية‪34222506 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34293604‬تاريخه‪1434/8/10:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة بقصــد الترويــج ‪ -‬قــات ‪ -‬هــروب ‪ -‬التعزيــر بالســجن‬\n                                                      ‫واجللــد والغرامــة ماليــة‪.‬‬\n\n\n\n\n                        ‫‪-1‬قرار مجلس الوزراء رقم (‪ )11‬يف ‪1374/2/1‬هـ ‪.‬‬\n                         ‫‪ -2‬األمر السامي رقم (‪ )59633‬يف ‪1432/12/9‬هـ‪.‬‬\n          ‫‪ -3‬املادة الثالثة من قرار وزير الداخلية رقم ‪2057‬يف ‪1404/5/26‬هـ‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة قــات بقصــد الترويــج‬\n      ‫وطلــب إثبــات مــا أســند إليــه وتعزيــره ‪،‬وتعزيــره علــى هروبــه مــن رجــال‬\n      ‫األمــن ‪،‬حيــث مت القبــض علــى املدعــى عليــه بعــد هروبــه وعــدم توقفــه‬\n      ‫وبتفتيــش الســيارة املســروقة والتــي كان يقودهــا مت العثــور علــى نبــات‬\n      ‫القــات وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة‬\n      ‫لنبــات القــات احملظــور وأنكــر املدعــى عليــه الدعــوى ‪،‬وبنــاء علــى مــا‬\n      ‫تقــدم حكمــت احملكمــة بتعزيــره بســجنه ثــاث ســنوات وغرامــة ماليــة‬\n      ‫قدرهــا خمســة آالف تــودع يف بيــت املــال تعزيــره بجلــده أربعمائــة جلــدة‬\n      ‫مفرقــة علــى دفعــات مقــدار كل دفعــه خمســون لقــاء هروبــه مــن رجــال‬\n      ‫الئحة‪،‬وصــدق‬\n            ‫ُ‬            ‫األمــن وقنــع املدعــى عليــه واعتــرض املدعــي العــام بــدون‬\n\n‫‪157‬‬\n\f                                        ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بجــازان برقــم ‪ 34222506‬وتاريــخ ‪1434/05/14‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341181955‬وتاريــخ ‪1434/05/14‬ه ـ ففــي يــوم‬\n‫االثنــن املوافق‪1434/5/27‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 15‬وفيهــا‬\n‫حضــر املدعــي العــام ‪.....‬بالتعميــد رقــم (‪ ).....‬وتاريــخ ‪1433/3/22‬ه ـ‬\n‫واملدعــى عليــه ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ( ‪).....‬‬\n‫وقــدم املدعــي العــام دعــوى محــررة تتضمــن ‪ :‬أنــه بتاريــخ ‪1434/4/11‬هـ‬\n‫وأثنــاء قيــام إحــدى دوريــات شــرطة محافظــة بيــش بعملهــا مت مشــاهدة‬\n‫ســيارة مــن نــوع ‪....‬حتمــل لوحــة رقــم (‪ ).....‬اللــون أبيــض (محجــوزة‬\n‫حلــن مراجعــة مالكهــا) علــى طريــق بيــش وعندمــا طلــب مــن قائدهــا‬\n‫االســتيقاف رفــض الوقــوف ومت اإلبــاغ عنــه ومتابعــة الســيارة وتوجــه‬\n‫بالطريــق الرملــي ومتــت املســاندة مــن قبــل دوريــة أخــرى ومت القبــض علــى‬\n‫الســيارة والذ قائدهــا بالفــرار ومت متابعتــه والقبــض عليــه واتضــح أن‬\n‫الســيارة مســروقة (مت إصــدار اإلجــراء النظامــي حيــال ذلــك) ومعمــم‬\n‫عنهــا بالتعميــم رقــم ‪.....‬وتاريــخ ‪1434/3/26‬ه ـ (لــدى شــرطة منطقــة‬\n‫عســير) وبتفتيــش الســيارة عثــر بهــا علــى كميــة مــن نبــات القــات بلــغ‬\n‫وزنها(‪227,995‬كجــم) مائتــان وســبعة وعشــرون كيلــو وتســعمائة‬\n‫وخمســة وتســعون جرام ـ ًا وأثبــت التقريــر الكيميائــي الشــرعي رقــم‬\n‫(‪ ).....‬وتاريــخ ‪1434/4/ 21‬ه ـ إيجابيــة العينــة املرســلة منــه لنبــات‬\n\n                                                                                   ‫‪158‬‬\n\f      ‫القــات احملظــور وباســتجواب املدعــى عليــه أنكــر حيازتــه للكميــة‬\n      ‫املضبوطــة مــن نبــات القــات احملظــور وأفــاد بأنــه كان حينهــا يف وادي‬\n      ‫‪.....‬عنــد قطيــع مــن الغنــم تعــود لــه وكان برفقتــه شــخص مينــي مجهــول‬\n      ‫الهويــة وعنــد مشــاهدته للفــرد أثنــاء قدومــه الذ بالفــرار ومت القبــض‬\n      ‫عليــه وال يعلــم بالســيارة ومــا ضبــط بهــا مــن كميــة القــات وليــس‬\n      ‫لديــه أي علــم أو عالقــة بذلــك وقــد أســفر التحقيــق معــه عــن توجيــه‬\n      ‫االتهــام إليــه بحيازتــه ملــا وزنــه (‪227،995‬كجــم) مائتــان وســبعة‬\n      ‫وعشــرون كيلــو وتســعمائة وخمســة وتســعون جرام ـ ًا مــن نبــات القــات‬\n      ‫احملظــور بقصــد الترويــج وهروبــه مــن رجــال األمــن وذلــك لألدلــة‬\n      ‫والقرائــن التاليــة ‪ - 1:‬مــا ورد مبحضــر القبــض والتفتيــش املشــار‬\n      ‫لــه املرفــق بــاألوراق ‪ -2‬مــا ورد بالتقريــر الكيميائــي الشــرعي املنــوه‬\n      ‫عنــه املرفــق وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم شــرع ًا‬\n      ‫ومعاقــب عليــه نظام ـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام‬\n      ‫‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات لــذا أطلــب مــا يلــي‪ :‬إثبــات إدانتــه‬\n      ‫مبــا أســند إليــه واحلكــم عليــه مبــا يلــي‪ -1 :‬بتعزيــره يف ضــوء املــادة‬\n      ‫(الثالثــة) مــن القــرار الــوزاري املشــار إليــه أعــاه إنفــاذا لألمــر الســامي‬\n      ‫الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ ‪ -2‬معاقبتــه لقــاء‬\n      ‫هروبــه مــن رجــال األمــن وبســؤال املدعــى عليــه ‪.....‬ســعودي اجلنســية‬\n      ‫ا هكــذا أجــاب‬     ‫أجــاب باإلنــكار لدعــوى املدعــي العــام جملــة وتفصيـ ً‬\n      ‫املدعــى عليــه عنــد ذلــك ســألت املدعــي العــام هــل لديــه بينــة علــى إدانــة‬\n      ‫املدعــى عليــه املذكــور بحيــازة كميــة نبــات القــات احملظــور املضبوطــة‬\n      ‫لقصــد الترويــج فقــال لــدى البينــة علــى ذلــك ومســتعد بإحضارهــا‬\n      ‫وأجلــت القضيــة لذلــك ويف يــوم الســبت املوافــق ‪1434/7/1‬ه ـ افتتحــت‬\n\n\n‫‪159‬‬\n\f‫اجللســة بــن املدعــي العــام واملدعــى عليــه ‪.....‬ســعودي اجلنســية وأحضــر‬\n‫املدعــي العــام شــهود هــم ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ( ‪ ).....‬و‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ( ‪).....‬‬\n‫و‪.....‬سعودي‪.....‬اجلنســية مبوجــب الســجل املدنــي رقــم ( ‪ ).....‬ويعملــون‬\n‫ا‬\n‫جميع ـ ًا بشــرطة محافظــة بيــش وشــهد كل واحــد منهــم مبفــرده قائ ـ ً‬\n‫أشــهد هلل تعالــى أنــه بتاريــخ ‪1434/4/11‬ه ـ ويف متــام الســاعة اخلامســة‬\n‫والنصــف مســاء وأثنــاء عملنــا بدوريــة علــى خــط ‪..........‬التابعــة حملــا‬\n‫فظــة بيــش شــاهدنا ســيارة موديــل ( ‪2010‬م) حتمــل اللوحــة رقــم ( ‪).....‬‬\n‫اشــتبهنا فيهــا لســرعة قائدهــا فأشــرنا لــه بالتوقــف فلــم يتوقــف فقمنــا‬\n‫مبطاردتــه حتــى نــزل علــى طريــق رملــي وقــد متــت مســا ندتنــا مــن قبــل‬\n‫دوريــة أخــرى حتــى متــت الســيطرة علــى الســيارة املذكــورة وقائــده وعنــد‬\n‫محاصرتــه مــن قبلنــا إال أن قائــد الســيارة هــذا احلاضــر أمــا منــا الــذي‬\n‫اتضــح لنــا أن اســمه ‪ .....‬ســعودي اجلنســية الذ بالفــرار وقمنــا مبطاردتــه‬\n‫وعلــى بعــد مائــة متــر مــن موقــع القبــض علــى ســيارته مت القبــض عليــه‬\n‫هــو شــخصي ًا وعندمــا قمنــا بتفتيــش ســيارته املذكــورة وجــد بداخلهــا‬\n‫كميــة مــن نبــات القــات احملظــور بلــغ وزنهــا مائتــان وســبعه وعشــرون‬\n‫كيلــو وتســعمائة وخمســه وتســعون جرامـ ًا وعنــد محاصرتــه مــن قبلنــا‬\n‫إال أن قائــد الســيارة هــذا احلاضــر أمــا منــا الــذي اتضــح لنــا أن اســمه‬\n‫‪ .....‬ســعودي اجلنســية الذ بالفــرار وقمنــا مبطاردتــه وعلــى بعــد مائــة متــر‬\n‫مــن موقــع القبــض علــى ســيارته مت القبــض عليــه هــو شــخصي ًا وعندمــا‬\n‫قمنــا بتفتيــش ســيارته املذكــورة وجــد بداخلهــا كميــة مــن نبــات القــات‬\n‫احملظــور بلــغ وزنهــا مائتــان وســبعه وعشــرون كيلــو وتســعمائة وخمســه‬\n‫وتســعون جرام ـ ًا فتــم القبــض علــى قائــد الســيارة املدعــى عليــه وعلــى‬\n\n\n                                                                                     ‫‪160‬‬\n\f      ‫كميــة القــات املذكــورة كمــا اتضــح لنــا أن لوحــة الســيارة املذكــورة‬\n      ‫ال تتبــع الســيارة املقبــوض عليهــا بــل هــي باســم ســيارة أخــرى مســروقة‬\n      ‫موديــل ( ‪2009‬م ) معمــم عنهــا مــن قبــل شــرطة الشــعب بعســير فعملنــا‬\n      ‫محضــر ًا بذلــك وتســليم املدعــى عليــه مــع املضبوطــات لشــرطة بيــش‬\n      ‫التخــاذ الــازم هــذا مــا لدينــا مــن شــهادة عنــد ذلــك ســألت املدعــي‬\n      ‫العــام هــل لديــه زيــادة بينــة ســوى مــن أحضــر فقــال ال بينــة لــدى ســوى‬\n      ‫مــن أحضــرت وأكتفــي بشــهادتهم عنــد ذلــك ســألت املدعــى عليــه هــل‬\n      ‫لــه جــرح يف شــهود املدعــي العــام فقــال ال أجــرح يف شــهادتهم بشــيء‬\n      ‫عنــد ذلــك طلــب مــن املدعــي العــام تزكيــة شــهوده فأحضــر كل مــن‬\n      ‫‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ( ‪ ).....‬و‪.....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ( ‪ ).....‬وشــهدا بعدالــة شــهود‬\n      ‫املدعــي العــام كل مــن ‪.....‬و‪.....‬و‪.....‬وأنهــم عــدول ثقــات ال قــادح فيهــم‬\n      ‫عنــد ذلــك جــرى منــا االطــاع علــى التقريــر الكيميائــي الشــرعي وعلــى‬\n      ‫ـاء‬\n      ‫محضــري الــوزن والقبــض فوجــدت متطابقــة ملــا جــاء بالدعــوى وبنـ ً‬\n      ‫علــى مــا ذكــر مــن دعــوى املدعــي العــام وعلــى إجابــة املدعــى عليــه ‪.....‬‬\n      ‫ســعودي اجلنســية باإلنــكار ملــا نســب لــه مــن نقــل مــا وزنــه مئتــان وســبعه‬\n      ‫وعشــرون كيلــو وتســعمائة وخمســة وتســعون جرامـ ًا مــن نبــات القــات‬\n      ‫احملظــور لقصــد الترويــج والهــروب مــن رجــال األمــن وبنــاء علــى مــا جــاء‬\n      ‫بشــهادة شــهود املدعــي العــام املعدلــن شــرع ًا لعــدم اجلــرح فيهــم مــن قبــل‬\n      ‫املدعــى عليــه لــذا فقــد ثبــت لــدى شــرع ًا إدانــة املدعــى عليــه املذكــور‬\n      ‫بنقــل كميــة نبــات القــات احملظــور املوضــح أعــاه لقصــد الترويــج وهــو‬\n      ‫يســتحق العقوبــة علــى ذلــك وفــق املــادة الثالثــة مــن قــرار وزيــر الداخليــة‬\n      ‫رقــم ‪ 2057‬وتاريخ‪1402/5/26‬ه ـ اســتناد ًا لقــرار مجلــس الــوزراء رقــم‬\n\n\n‫‪161‬‬\n\f‫(‪ )11‬وتاريــخ ‪1374/2/1‬ه ـ وإنفــاذ ًا لألمــر الســامي الكــرمي رقــم‬\n‫‪ 59633‬وتاريــخ ‪1432/12/9‬ه ـ وملــا ذكــر أعــاه ولعــدم وجــود ســوابق‬\n‫عليــه فقــد حكمــت بتعزيــره مبــا يلــي‪ :‬أو ًال ‪ /‬يعــزر بالســجن ملــدة ثــاث‬\n‫ســنوات مــن تاريــخ إيقافــه علــى ذمــة القضيــة يف ‪1434/4/11‬ه ـ ثانيـ ًا ‪/‬‬\n‫يعــزر باجللــد لقــاء ذلــك ولقــاء الهــروب مــن رجــال األمــن بأربعمائــة جلــدة‬\n‫علن ـ ًا مفرقــة كل دفعــة خمســون جلــدة بــن الدفعــة واألخــرى عشــرة‬\n‫أيــام ثالث ـ ًا ‪ /‬يدفــع غرامــة ماليــة قدرهــا خمســة اآلف ريــال تــودع بيــت‬\n‫مــال املســلمني هــذا مــا حكمــت بــه وبعرضــه علــى الطرفني قــرر املدعى‬\n‫عليــه القناعــة وطلــب املدعــي العــام اســتئناف احلكــم مكتفيـ ًا بالئحــة‬\n‫االدعــاء العــام وأمــرت بتنظيــم القــرار الــازم مبوجبــه ورفعــه حملكمــة‬\n‫االســتئناف مبنطقــة عســير لدراســته وابــداء مــا تــراه نحــوه وصلــى اهلل‬\n    ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/7/5‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمة اجلزائية بجــازان رقم ‪341181955‬‬\n‫وتاريــخ ‪1434/7/15‬ه ـ املرفــق بهــا القــرار الشــرعي الصــادر مــن فضيلة‬\n‫القاضي باحملكمة الشــيخ‪..... /‬رقم ‪ 34262414‬وتاريخ ‪1434/7/9‬هـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد‪ (..... /‬ســعودي اجلنســية ) يف قضيــة‬\n‫( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                            ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                       ‫‪162‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":157,"source_page_end":162,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"44c7d35cb4dfca2be68013d274b9909871411f1b378c85b7651484707fb24e86","normalized_text_hash":"b0f3dca22a41ed9c8f41ff900a436655cf0c9dc1da86cc9752c1857d6c3aadd5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p157-34262414"},{"id":"f99f0a67-8812-5eb5-a8fb-aab2da658619","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -اشتراك يف حيازة حشيش بقصد التعاطي -تعاطي احلشيش -قيادة السيارة حتت تأثيره -تستر على مصدره -إقامة حد املسكر على متعاطي املخدرات -الهروب من رجال األمن -إقرار -إدانة -التعزير بالسجن واجللد واملنع من السفر .","document_number":"34261315","case_number":"34224522","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/08","year":"1434","subject":"مخدرات -اشتراك يف حيازة حشيش بقصد التعاطي -تعاطي احلشيش -قيادة السيارة حتت تأثيره -تستر على مصدره -إقامة حد املسكر على متعاطي املخدرات -الهروب من رجال األمن -إقرار -إدانة -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34261315 :‬تاريخه‪1434/07/08 :‬هـ‬\n                           ‫رقم الدعوى‪34224522:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 34284538‬تاريخه‪1434/8/1:‬هـ‬\n\n\n       ‫مخــدرات‪ -‬اشــتراك يف حيــازة حشــيش بقصــد التعاطــي‪ -‬تعاطــي‬\n       ‫احلشــيش ‪ -‬قيــادة الســيارة حتــت تأثيــره ‪ -‬تســتر علــى مصــدره ‪ -‬إقامــة‬\n       ‫حــد املســكر علــى متعاطــي املخــدرات ‪ -‬الهــروب مــن رجــال األمــن‪ -‬إقــرار‬\n                        ‫‪ -‬إدانــة ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n        ‫املواد (‪ )3‬و(‪ )41‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليهــم بإدانتهــم باالشــتراك يف حيــازة‬\n       ‫احلشــيش املخــدر بقصــد التعاطــي وتعاطــي الثانــي لــه وشــرب األول‬\n       ‫والثالــث للمســكر وقيــادة األول للســيارة حتــت تأثيــره وهروبهــم مــن‬\n       ‫رجــال األمــن وتســترهم علــى مصــدر املخــدر ‪ ،‬واحلكــم عليهــم بعقوبــة‬\n       ‫الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات‬\n       ‫العقليــة مــع إفهــام األول بــأن عقوبتــه علــى قيــادة الســيارة حتــت تأثيــر‬\n       ‫املســكر تقــرر مــن اجلهــة املختصــة واحلكــم عليهــم بعقوبــة تعزيريــة‬\n       ‫علــى باقــي التهــم حيــث إنــه مت القبــض عليهــم وهــم يف حالــة غيــر‬\n       ‫طبيعيــة أثنــاء محاولتهــم الهــرب راجلــن بعــد اصطــدام ســيارتهم مبقبــرة‬\n       ‫وبتفتيــش الســيارة عثــر فيهــا علــى قطعــة مــن احلشــيش ‪ ،‬أثبــت التقريــر‬\n\n‫‪163‬‬\n\f‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخــدر‪ ،‬أقــر‬\n‫املدعــى عليهــم أمــام احملكمــة بجميــع مــا أســنده إليهــم املدعــي العــام‬\n‫ســوى اشــتراكهم يف حيــازة احلشــيش املخــدر فقــد أقــر الثانــي بــأن‬\n‫املضبــوط عائــد لــه وال عالقــة لــأول والثالــث بــه‪ ،‬وثبــت أن املدعــي‬\n‫العــام لــم يقــدم بينــات كافيــة إلثبــات مــا يدعيــه مــن االشــتراك‪ ،‬بنــاء‬\n‫علــى مــا تقــدم حكمــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي‬\n‫العــام باشــتراك املدعــى عليهــم يف حيــازة املخــدر كمــا قضــت بإدانــة‬\n‫املدعــى عليهــم بشــرب املســكر والهــروب مــن رجــال األمــن وحيــازة‬\n‫الثانــي للحشــيش بقصــد التعاطــي وتســتره علــى مصــدر املخــدر‪،‬‬\n‫وقــررت جلــد كل واحــد منهــم حــد املســكر ثمانــن جلــدة دفعــة واحــدة‬\n‫علنــا‪ ،‬كمــا قــررت ســجن الثانــي ملــدة ســتة أشــهر وجلــده خمســن جلــدة‬\n‫ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني لقــاء حيــازة احلشــيش‬\n‫والتســتر علــى مصــدره‪ ،‬وســجن الثانــي والثالــث ملــدة شــهر وســجن األول‬\n‫ملــدة خمســة أشــهر وجلــد كل واحــد منهــم مائــة جلــدة لقــاء هروبهــم‬\n‫مــن رجــال األمــن‪ ،‬وقنــع املدعــى عليهــم باحلكــم وعــارض املدعــي العــام‬\n           ‫عليــه‪ ،‬وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ................‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة باخلــرج املكلــف برقــم ‪ 34224522‬وتاريــخ‬\n‫‪1434/05/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341191106‬وتاريــخ‬\n‫‪1434/05/15‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1434/07/04‬ه ـ فتحــت‬\n\n                                                                                    ‫‪164‬‬\n\f      ‫اجللســة وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق واالدعــاء العــام‬\n      ‫مبحافظــة اخلــرج وادعــى علــى احلاضريــن معــه يف املجلــس الشــرعي ‪........‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬و ‪ ........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬و ‪ ........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ........‬قائــا يف حتريــر دعــواه عليهــم‬\n      ‫بصفتــي مدعيـ ًا عامـ ًا بدائــرة التحقيــق واالدعــاء العــام مبحافظــة اخلــرج‬\n      ‫أدعــي علــى كل مــن‪ ،........ -1:‬البالــغ مــن العمر(‪)24‬عام ـ ًا ‪........ ،‬‬\n      ‫‪ ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ ).......‬متعلــم ‪،‬‬\n      ‫قبــض عليــه بتاريــخ ‪1434/4/12‬ه ـ وأودع قســم ســجن محافظــة اخلــرج‬\n      ‫بأمــر إحالــة ومتديــد توقيــف رقــم ‪ 2567‬وتاريــخ ‪1434/ 4 /21‬هـ اســتناد ًا‬\n      ‫لبرقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم ‪ 45781‬وتاريــخ‬\n      ‫‪10431/7/22‬ه ـ ‪ -2‬البالــغ مــن العمر(‪)20‬عام ـاً‪ ........ ،‬ســعودي‬\n      ‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ )......‬متعلــم طالــب بكليــة‬\n      ‫التقنيــة ‪ ،‬يســكن محافظــة اخلــرج حــي ‪ ........‬قبــض عليــه بتاريــخ‬\n      ‫‪1434/4/12‬ه ـ وأفــرج بتاريــخ ‪1434/4/15‬ه ـ اســتنادا للمــادة(‪)120‬‬\n      ‫مــن نظــام اإلجــراءات اجلزائيــة‪، -3 .‬البالــغ مــن العمر(‪)22‬عام ـ ًا ‪........‬‬\n      ‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ........‬متعلــم ‪ ،‬عاطــل عــن‬\n      ‫العمــل‪ ،‬يســكن محافظــة اخلــرج حــي ‪ ........‬قبــض عليــه بتاريــخ‬\n      ‫‪1434/4/12‬ه ـ وأفــرج بتاريــخ ‪1434/4/15‬ه ـ اســتنادا للمــادة(‪)120‬‬\n      ‫مــن نظــام اإلجــراءات اجلزائيــة‪ .‬أنــه بتاريــخ ‪1434/4/12‬ه ـ مت القبــض‬\n      ‫علــى املدعــى عليهــم مــن قبــل إحــدى فــرق دوريــات األمــن مبحافظــة‬\n      ‫اخلــرج أثنــاء عملهــا بعــد االشــتباه بســيارة مــن نــوع (‪ )....‬لونهــا أســود رقــم‬\n      ‫لوحتهــا (‪ )....‬كــون قائدهــا املدعــى عليــه األول مــن األشــخاص‬\n\n\n‫‪165‬‬\n\f‫املشــبوهني ويقــل األحــداث معــه وعنــد محاولــة اســتيقافه قــام بالهــرب‬\n‫ولتهــوره مت أخــذ رقــم لوحــة ســيارته وأثنــاء مســح الفرقــة لالســتراحات‬\n‫يف حــي ‪ .......‬شــوهدت الســيارة املشــار إليهــا وعنــد مشــاهدته للفرقــة‬\n‫قــام بالهــرب بســرعة جنونيــة ومــع أحــد املنعطفــات القريبــة مــن مقبــرة‬\n‫‪ ........‬فقــد الســيطرة علــى الســيارة وارتطمــت الســيارة بجــدار املقبــرة‬\n‫ارتطامـ ًا خفيفـ ًا (متــت معاجلــة موضــوع االصطــدام مــن قبــل شــعبة املــرور)‬\n‫فقــام قائــد الســيارة املدعــى عليــه (األول) ومعــه مرافقيــه (الثانــي)‬\n‫بالهــرب إلــى داخــل املقبــرة فتــم البحــث عنهمــا ومت القبــض عليهمــا‬\n‫بداخــل املقبــرة وقبــض علــى (الثالــث ) داخــل الســيارة وقــد كان املدعى‬\n‫عليهــم بحالــه غيــر طبيعيــة وبتفتيشــهم والســيارة عثــر علــى قطعــة يشــتبه‬\n‫أن تكــون حشيش ـ ًا مخــدر ًا مثبتــه علــى الديكــور بالقــرب مــن ناقــل‬\n‫احلركــة بلــغ وزنهــا (‪ )2,5‬جرامــن وخمســة أعشــار اجلــرام اثبت التقرير‬\n‫الكيميائــي الشــرعي(رقم‪/4400‬س لعام‪1434‬ه ـ )‪ .‬إيجابيــة العينــة‬\n‫املضبوطــة املرســلة للتحليــل ملــادة احلشــيش وهــو مــن املــواد املخــدرة‬\n‫املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وباســتجواب األول أقــر بشــرب املســكر والهــرب بســيارته مــن رجــال‬\n‫األمــن واالصطــدام بجــدار مقبــرة ‪ ....‬والهــروب علــى قدميــه والقبــض‬\n‫عليــه داخــل مقبــرة ‪ ......‬وباســتجواب الثانــي أقــر بتعاطــي احلشــيش‬\n‫املخــدر وعائديــه القطعــة املضبوطــة لــه لغــرض التعاطــي وانــه وضعهــا يف‬\n‫جيــب بنطالــه بعــد لفــه لهــا بكيــس علبــة الدخــان ثــم قــام برميهــا علــى‬\n‫األرض عنــد القبــض عليــه ‪ ،‬وهربــه مــن رجــال األمــن والقبــض عليــه‬\n‫داخــل املقبــرة وان رفيقيــه ال يعلمــان بوجــود قطعــة احلشــيش معــه وليــس‬\n\n\n                                                                                     ‫‪166‬‬\n\f      ‫لهمــا عالقــة بهــا‪ .‬باســتجواب الثالــث أقــر بشــرب املســكر ومشــاهدته‬\n      ‫لقطعــة احلشــيش املخــدر بيــد املدعــى عليــه الثانــي دون أن يلفهــا بشــيء‪.‬‬\n      ‫وقــد انتهــى التحقيــق معهــم إلــى توجيــه االتهــام للمدعــى عليهــم‬\n      ‫باالشــتراك بحيــازة قطعــة مــن احلشــيش املخــدر تــزن (‪ )2,5‬جرامــن‬\n      ‫وخمســة أعشــار اجلــرام لغــرض التعاطــي وتعاطــي الثانــي للحشــيش‬\n      ‫املخــدر املجــرم بالفقــرة (الثانيــة) مــن املادة(الثالثــة ) مــن نظــام مكافحة‬\n      ‫املخــدرات واملؤثــرات العقليــة املشــار إليــه وشــرب األول والثالــث‬\n      ‫للمســكر وتســترهم جميع ـ ًا علــى مصــدر املخــدر املضبــوط معهــم‬\n      ‫وهروبهــم مــن رجــال األمــن وقيــادة األول الســيارة حتــت تأثيــر املســكر‬\n      ‫املجــرم بالفقــرة رقــم (‪ )8‬مــن جــدول املخالفــات رقــم (‪ )1‬امللحــق بنظــام‬\n      ‫املــرور الصــادر باملرســوم امللكــي رقــم (‪/85‬م) وتاريــخ ‪1428/10/26‬هـ‬\n      ‫املعاقــب عليــة شــرع ًا وذلــك لألدلــة والقرائــن التالية‪ -1 :‬مــا ورد مبحضر‬\n      ‫القبــض والتفتيــش املنــوه عنــه املرفــق علــى لفــة رقــم (‪ -2 .)1‬إقــرار األول‬\n      ‫املنــوه عنــه املــدون علــى الصفحــة رقــم ( ‪ )6-5‬مــن دفتــر التحقيــق املرفــق‬\n      ‫علــى اللفــة رقــم ( ‪ -3 .) 28‬إقــرار الثانــي املنــوه عنــه املــدون على الصفحة‬\n      ‫رقــم ( ‪ )2-1‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم ( ‪ -4 .) 28‬إقــرار‬\n      ‫الثالــث املنــوه عنــه املــدون علــى الصفحــة رقــم ( ‪ )4-3‬مــن دفتــر التحقيــق‬\n      ‫املرفــق علــى اللفــة رقــم (‪ -5 .) 28‬مــا تضمنــه التقريــر الكيميائــي‬\n      ‫الشــرعي املنــوه عنــه املرفــق لفــه رقــم ( ‪ ) 54‬وببحــث ســوابقهم تبــن‬\n      ‫وجــود ســابقة حيــازة مخــدرات مســجله بحــق املدعــى عليــه األول ولــم‬\n      ‫يتبــن وجــود ســوابق جنائيــة مســجلة بحــق املدعــى عليهمــا الثانــي‬\n      ‫والثالــث‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليهــم‪ -‬وهــم بكامــل‬\n      ‫أهليتهــم املعتبــرة شــرعاً‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا ومجــرم‬\n\n\n‫‪167‬‬\n\f‫ومعاقــب عليــه نظام ـ ًا أطلــب إثبــات إدانتهــم مبــا ُأ ْس ـن َِد إليهــم واحلكــم‬\n‫عليهــم مبــا يلــي‪ -1 :‬بعقوبــة حــد املســكر لــأول والثالــث لقــاء شــربهما‬\n‫لــه‪-2 .‬بعقوبــة لهــم جميع ـ ًا وفق ـ ًا للفقــرة (األولــى) مــن املــادة (‪ )41‬مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه لقــاء حيازتهــم‬\n‫مــا ضبــط معهــم مــن مخــدر لغــرض التعاطــي ‪ ،‬ولقــاء تعاطــي الثانــي‬\n‫للحشــيش املخــدر‪ -3 .‬منعهــم مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء‬\n‫تنفيذهــم عقوبــة الســجن وفق ـ ًا للفقــرة (األولــى ) مــن املــادة (‪ )56‬مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه‪-4 .‬بعقوبــة‬\n‫تعزيريــة زاجــرة لهــم ورادعــة لغيرهــم لقــاء هروبهــم مــن رجــال األمــن ‪،‬‬\n‫ولقــاء تســترهم علــى مصــدر املخــدر املضبــوط معهــم وفق ـ ًا لتعميــم‬\n‫صاحــب الســمو امللكــي أميــر منطقــة الريــاض بالنيابــة رقــم‬\n‫(‪ )10283/9/101‬وتاريــخ ‪1430/5/17‬هــ‪-5 .‬إثبــات إدانــة األول بقيادة‬\n‫الســيارة حتــت تأثيــر املســكر وفــق الفقــرة رقــم (‪ )8‬مــن اجلــدول رقــم‬\n‫(‪ )1‬امللحــق بنظــام املــرور الصــادر باملرســوم امللكي رقــم (‪/85‬م) وتاريخ‬\n‫‪1428/10/26‬ه ـ وإفهامــه بــأن عقوبتــه الــواردة بالفقــرة رقــم (‪ )1‬مــن‬\n‫املــادة رقــم (‪ )68‬مــن نظــام املــرور املشــار إليــه تقــرره اجلهــة املختصــة وفــق‬\n‫الفقــرة رقــم (‪ )2‬مــن قــرار مجلــس الــوزراء رقــم (‪ )315‬وتاريــخ‬\n‫‪1428/10/26‬ه ـ هــذه دعــواي وأســأل املدعــى عليهــم اجلــواب وبســؤال‬\n‫املدعــى عليــه األول عــن دعــوى املدعــي العــام أجــاب قائــا إن مــا ذكــره‬\n‫املدعــي العــام يف دعــواه مــن أنــه مت القبــض علينــا أنــا وزمالئــي املدعــى‬\n‫عليهــم بتاريــخ ‪1434/4/12‬ه ـ مــن قبــل الدوريــات األمنيــة فهــذا صحيــح‬\n‫‪ ،‬وقــد كنــا علــى ســيارة مــن نــوع ‪ ....‬ســوداء اللــون عائــدة ألخــي بقيادتــي‬\n‫أنــا وقــد كنــت أنــا وزميلــي املدعــى عليــه يف حالــة ســكر لشــربنا العــرق‬\n\n\n                                                                                           ‫‪168‬‬\n\f      ‫املســكر أمــا املدعــى عليــه الثانــي فلــم يكــن ســكرانا فلمــا شــاهدنا‬\n      ‫الدوريــة قمنــا بالهــرب منهــا بســرعة جنونيــة واصطدمــت بعدهــا بجــدار‬\n      ‫املقبــرة ثــم قمــت أنــا بالنــزول مــن الســيارة والهــرب علــى أقدامنــا إلــى‬\n      ‫داخــل املقبــرة ثــم مت القبــض علينــا هنــاك وقبــض علــى زميلي يف الســيارة‬\n      ‫وبالنســبة للحشــيش الــذي وجــد مــع زميلــي فــا عالقــة لــي بــه فهــو‬\n      ‫يخصــه وحــده وأنــا لــم أتعــاط احلشــيش وبالنســبة للســابقة فهــي صحيحة‬\n      ‫وقــد نلــت جزائــي عليهــا وأنــا تائــب هلل تعالــى هــذا مــا لــدي‪ .‬وبعــرض‬\n      ‫دعــوى املدعــي العــام علــى املدعــى عليــه الثانــي وســؤاله عنهــا أجــاب‬\n      ‫قائــا إن مــا ذكــره املدعــي العــام مــن أنــه مت القبــض علينــا بتاريــخ‬\n      ‫‪1434/4/12‬ه ـ مــن قبــل الدوريــات األمنيــة بعــد هربنــا علــى الســيارة‬\n      ‫التــي كان يقودهــا املدعــى عليــه فهــذا صحيــح ثــم اصطــدم زميلــي‬\n      ‫بجــدار املقبــرة فنزلــت أنــا وإيــاه مــن الســيارة وهربنــا علــى أقدامنــا إلــى‬\n      ‫داخــل املقبــرة ومت القبــض علينــا هنــاك ‪ ،‬ولــم أشــرب املســكر يف ذلــك‬\n      ‫اليــوم مــع زميلــي ‪ ،‬وبالنســبة لقطعــة احلشــيش التــي وجــدت بحوزتــي‬\n      ‫فهــذا صحيــح وقــد بلــغ وزنهــا جرامــن وخمســة أعشــار اجلــرام وكنــت‬\n      ‫أنــوي اســتعمالها وأنــا أتعاطــى احلشــيش املخــدر منــذ مــا يقــارب الســنتني‬\n      ‫وليــس لزمالئــي املدعــى عليهمــا عالقــة بقطعــة احلشــيش التــي وجــدت‬\n      ‫بحوزتــي فهــي تخصنــي أنــا وحــدي وقــد اشــتريتها مــن الريــاض مــن‬\n      ‫شــخص ال أعرفــه وليــس علــي ســوابق مســجلة وهلل احلمــد هــذا مــا لــدي‬\n      ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه الثالــث وســؤاله عنهــا‬\n      ‫أجــاب قائــا إن مــا ذكــره املدعــي العــام مــن أنــه مت القبــض علينــا‬\n      ‫بتاريــخ ‪1434/4/12‬ه ـ أنــا وزمالئــي املدعــى عليهــم مــن قبــل الدوريــات‬\n      ‫األمنيــة بعــد هروبنــا منهــم واصطدامنــا بجــدار املقبــرة فهــذا صحيــح‬\n\n\n‫‪169‬‬\n\f‫وقــد كنــت أنــا وزميلــي ســكرانني أمــا املدعــى عليــه الثانــي فلــم يكــن‬\n‫ســكرانا ولكــن كانــت معــه قطعــة مــن احلشــيش املخــدر ‪ ،‬وال عالقــة‬\n‫لــي بهــذه القطعــة ولــم أشــترك معــه فيهــا وإمنــا هــو أحضرهــا لوحــده‬\n‫فقــط وليــس علــي ســوابق مســجلة وهلل احلمــد هــذا مــا لــدي ثــم جــرى‬\n‫ســؤال املدعــي العــام عــن بينتــه علــى اشــتراك املدعــى عليهمــا األول‬\n‫والثالــث مــع املدعــى عليــه الثانــي يف حيــازة قطعــة احلشــيش املخــدر‬\n‫فقــال بينتــي موجــودة يف أوراق املعاملــة أطلــب االطــاع عليهــا وبالرجــوع‬\n‫لكامــل أوراق املعاملــة وجــد مــن ضمنهــا محضــر القبــض والتفتيــش‬\n‫املــدون علــى اللفــة رقــم (‪ )1‬الصــادر مــن إدارة دوريــات األمــن مبنطقــة‬\n‫الريــاض برقــم ‪ 3188‬وتاريــخ ‪1434/4/12‬ه ـ واملتضمــن أنه مت االشــتباه‬\n‫بســيارة مــن نــوع ‪ .....‬ســوداء اللــون لكــون قائــد الســيارة مــن األشــخاص‬\n‫املشــبوهني ويقــل األحــداث وعنــد محاولــة اســتيقافه ارتكــب الهــروب‬\n‫ومت أخــذ الرقــم ‪ ،‬ثــم باشــرت الفــرق املســح وأثنــاء مســح اســتراحات‬\n‫اليمامــة عثــر علــى الســيارة وعندمــا شــاهد الفرقــة ارتكــب الهــروب‬\n‫بســرعة جنونيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/07/04‬ه ـ ومــع أحــد املنعطفــات‬\n‫القريبــة مــن مقبــرة ‪......‬فقــد الســيطرة علــى الســيارة وارتطمــت بجــدار‬\n‫املقبــرة صدمــة خفيفــة وقــام قائــد الســيارة وأحــد األحــداث بالهــروب‬\n‫داخــل املقبــرة ومت القبــض عليهــم والثالــث داخــل الســيارة وعنــد تفتيــش‬\n‫الســيارة عثــر علــى قطعــة حشــيش مثبتــة علــى ديكــور قــرب القيــر‬\n‫وبعرضــه علــى املدعــى عليهــم صادقــوا عليــه كمــا جــرى االطــاع علــى‬\n‫إقــرارات املدعــى عليهــم املدونــة علــى ملــف التحقيــق املرفــق علــى لفــة‬\n‫رقــم (‪ )28‬صــ(‪ )6-5-4-3-2-1‬واملتضمنــة طبــق مــا ورد يف إجابتهــم‬\n\n\n                                                                                   ‫‪170‬‬\n\f      ‫لدينــا وبعرضهــا عليهــم صادقــوا عليهــا ‪ ،‬كمــا جــرى االطــاع علــى‬\n      ‫التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة الســموم‬\n      ‫والكيميــاء الشــرعية بالريــاض برقــم ‪/44/2/4400‬ك وتاريــخ‬\n      ‫‪1434/4/20‬ه ـ املتضمــن إيجابيــة العينــة ملــادة احلشــيش املخــدر وهــو من‬\n      ‫املــواد املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة وبعرضــه علــى املدعــى عليهــم صــادق عليــه املدعــى‬\n      ‫عليــه وأمــا املدعــى عليهمــا فقــاال ال عالقــة لنــا بــه ‪ ،‬كمــا جــرى االطالع‬\n      ‫علــى صحيفــة ســوابق املدعــى عليهــم فتبــن وجــود ســابقة علــى املدعــى‬\n      ‫عليــه األول وهــي حيــازة مخــدرات وبعرضهــا علــى املدعــى عليــه األول‬\n      ‫صــادق عليهــا ‪ ،‬ثــم جــرى ســؤال الطرفــن هــل لديهمــا مــا يضيفانــه‬\n      ‫فقالــوا ليــس لدينــا مــا نضيفــه ‪ ،‬فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n      ‫العــام وإجابــة املدعــى عليهــم ونظــرا ملصادقــة املدعــى عليهــم علــى ما ورد‬\n      ‫يف دعــوى املدعــي العــام مــن قيامهــم بالهــرب مــن الدوريــة األمنيــة ‪،‬‬\n      ‫واالصطــدام بجــدار املقبــرة ونــزول املدعــى عليهمــا والهــرب علــى‬\n      ‫أقدامهمــا ‪ ،‬ومصادقــة املدعــى عليهمــا علــى شــرب العــرق املســكر ‪،‬‬\n      ‫ومصادقــة املدعــى عليــه علــى قيــادة الســيارة حتــت تأثيــر املســكر ‪،‬‬\n      ‫ونظــرا إلنــكار املدعــى عليهمــا االشــتراك مــع املدعــى عليــه يف حيــازة‬\n      ‫قطعــة احلشــيش املخــدر ‪ ،‬ونظــرا إلقــرار املدعــى عليــه بــأن تلــك القطعــة‬\n      ‫خاصــة بــه وال عالقــة للمدعــى عليهمــا بهــا ‪ ،‬ونظــرا إلقــراره كذلــك‬\n      ‫بتعاطيــه للحشــيش املخــدر منــذ مــا يقــارب الســنتني مــن تاريــخ القبــض‬\n      ‫عليــه ‪ ،‬ونظــرا إلنــكاره معرفــة الشــخص الــذي اشــترى منــه احلشــيش‬\n      ‫املخــدر‪ ،‬وبنــاء علــى مــا ورد يف التقريــر الكيميائــي الشــرعي مــن‬\n      ‫احتــواء العينــة علــى مــادة احلشــيش املخــدر ‪ ،‬وبنــاء علــى املــادة الثالثــة مــن‬\n\n\n‫‪171‬‬\n\f‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وبنــاء على املــادة احلادية‬\n‫واألربعــن واملــادة السادســة واخلمســن مــن ذات النظــام ‪ ،‬ونظــرا لكــون‬\n‫مــا قدمــه املدعــي العــام مــن بينــات علــى اشــتراك املدعــى عليهــم الثالثــة‬\n‫يف حيــازة قطعــة احلشــيش املخــدر غيــر كافيــة يف إثبــات مــا يدعيــه‬\n‫ونظــرا لكــون املدعــى عليهمــا ليســا مــن أربــاب الســوابق ‪ ،‬ونظــرا‬\n‫لوجــود ســابقة علــى املدعــى عليــه لــكل مــا تقــدم فقــد ثبــت لــدي قيــام‬\n‫املدعــى عليهــم الثالثــة بالهــرب مــن رجــال األمــن ‪ ،‬وقيــام املدعــى عليهما‬\n‫بشــرب العــرق املســكر ‪ ،‬وقيــام املدعــى عليــه بقيــادة الســيارة حتــت‬\n‫تأثيــر املســكر ‪ ،‬وقيــام املدعــى عليــه خالــد بحيــازة قطعــة مــن احلشــيش‬\n‫املخــدر بلــغ وزنهــا جرامــن وخمســة أعشــار اجلــرام بقصــد التعاطــي‬\n‫وتعاطيــه لنوعهــا يف الســابق وتســتره علــى مصدرهــا وقــررت مــا يلــي‪:‬‬\n‫أوال‪ /‬صــرف النظــر عــن دعــوى املدعــي العــام يف اشــتراك كال مــن‬\n‫املدعــى عليهمــا يف حيــازة قطعــة احلشــيش املذكــورة يف دعــوى املدعــي‬\n‫العــام واملطالبــة بعقوبتهمــا وفقــا للمــادة (‪ )41‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة ومنعهمــا مــن الســفر وتســترهم علــى‬\n‫مصــدر احلشــيش املخــدر‪ .‬ثانيــا‪ /‬جلــد املدعــى عليهمــا االول والثالــث‬\n‫ثمانــن جلــدة دفعــة واحــدة حــد املســكر أمــام مــأ مــن املســلمني‪ .‬ثالثــا‪/‬‬\n‫جلــد املدعــى عليــه الثانــي ثمانــن جلــدة دفعــة واحــد حــد املســكر لقــاء‬\n‫تعاطيــه الســابق أمــام مــأ مــن املســلمني‪ .‬رابعــا‪ /‬تعزيــر املدعــى عليــه‬\n‫بســجنه ســتة أشــهر مــن تاريــخ إيقافــه يف هــذه القضيــة لقــاء حيازتــه‬\n‫قطعــة احلشــيش املخــدر‪ .‬خامســا‪ /‬تعزيــر املدعــى عليــه بجلــده خمســن‬\n‫جلــدة دفعــة واحــدة لقــاء تســتره علــى مصــدر احلشــيش املخــدر‪ .‬سادســا‪/‬‬\n‫منــع املدعــى عليــه مــن الســفر خــارج اململكــة مــدة ســنتني بعــد انتهــاء‬\n\n\n                                                                                      ‫‪172‬‬\n\f      ‫محكوميتــه‪ .‬ســابعا‪ /‬تعزيــر املدعــى عليهمــا لقــاء هربهــا مــن رجــال‬\n      ‫األمــن بالســجن شــهرا وجلدهمــا مائــة جلــدة‪ .‬ثامنــا‪ /‬تعزيــر املدعــى عليــه‬\n      ‫لقــاء هروبــه مــن رجــال األمــن بســجنه خمســة أشــهر مــن تاريــخ إيقافــه يف‬\n      ‫هــذه القضيــة وجلــده مائــة جلــدة‪ .‬تاســعا‪ /‬تكــون هنــاك مــدة بــن تنفيــذ‬\n      ‫جلــد احلــد وجلــد التعزيــر قدرهــا خمســة عشــر يومــا ‪ ،‬ويكــون جلــد‬\n      ‫التعزيــر مفرقــا علــى دفعــات كل دفعــة خمســون جلــدة بــن الدفعــة‬\n      ‫واألخــرى شــهرا‪ .‬عاشــرا‪ /‬أفهمــت املدعــى عليــه االول بــأن عقوبتــه علــى‬\n      ‫قيــادة الســيارة حتــت تأثيــر املســكر عائــدة للجهــة املختصــة‪ .‬وبجميــع‬\n      ‫مــا تقــدم حكمــت وبعرضــه علــى الطرفــن قــرر املدعــى عليهــم القناعــة‬\n      ‫وقــرر املدعــي العــام عدمهــا وطلــب رفــع احلكــم حملكمــة االســتئناف‬\n      ‫بــدون الئحــة اعتراضيــة فأجبتــه لطلبــه‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/07/04‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يوم اخلميــس املوافق‪1434/08/25‬هـ فتحت‬\n      ‫اجللســة الســاعة ‪ 09 :30‬وفيهــا كانــت قــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف برقــم ‪ 34178612‬وتاريــخ ‪1434/8/10‬ه ـ بشــرح فضيلــة‬\n      ‫رئيــس احملكمــة رقــم ‪ 34/178612‬وتاريــخ ‪1434/8/16‬ه ـ وبرفقهــا‬\n      ‫القــرار الصــادر مــن الدائــرة الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة‬\n      ‫االســتئناف بالريــاض رقــم ‪ 34284538‬وتاريــخ ‪1434/8/1‬ه ـ املتضمــن‬\n      ‫املصادقــة علــى احلكــم وقــد ظهــر القــرار مبــا نصــه (احلمــد هلل وحــده‬\n      ‫وبعــد فقــد اطلعنــا علــى هــذا القــرار برقــم ‪ 34261315‬وتاريــخ‬\n      ‫‪1434/7/8‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪ /‬وأصدرنــا القــرار رقــم‬\n      ‫‪ 34284538‬وتاريــخ ‪1434/8/1‬ه ـ املتضمــن أنــه لــم يظهــر مــا يوجــب‬\n      ‫املالحظــة علــى احلكــم واهلل املوفــق قاضــي اســتئناف توقيعــه وختمــه‬\n\n\n‫‪173‬‬\n\f‫قاضــي اســتئناف توقيعــه وختمــه رئيــس الدائــرة د‪ .‬توقيعــه وختمــه ) أ‪.‬ه ـ‬\n‫لــذا جــرى أحلاقــه والتهميــش مبوجبــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n         ‫نبينا محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪ 1434/08/25‬هـ‪.‬‬\n\n\n\n\n                                                                                  ‫‪174‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":163,"source_page_end":174,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3f1a9e647d17fa48710b0be0d02773613af73c602a245365c6c2751ec69a1a5f","normalized_text_hash":"5e22a1a67d10c97091b37b9f88c29d48d09e0e7faea9a7ebb09f69043a8ba62d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p163-34261315"}]$archive_payload$::jsonb AS data)
